import React from "react";

const MAP = {
  disponible: { label: "Disponible", cls: "bg-emerald-100 text-emerald-800 border-emerald-200" },
  asignado: { label: "Asignado", cls: "bg-blue-100 text-blue-800 border-blue-200" },
  entregado: { label: "Entregado", cls: "bg-blue-100 text-blue-800 border-blue-200" },
  mantenimiento: { label: "Mantenimiento", cls: "bg-amber-100 text-amber-800 border-amber-200" },
  danado: { label: "Dañado", cls: "bg-red-100 text-red-800 border-red-200" },
  baja: { label: "De Baja", cls: "bg-slate-200 text-slate-700 border-slate-300" },
  reservado: { label: "Reservado", cls: "bg-violet-100 text-violet-800 border-violet-200" },
  transito: { label: "En Tránsito", cls: "bg-cyan-100 text-cyan-800 border-cyan-200" },
  // tickets
  abierto: { label: "Abierto", cls: "bg-blue-100 text-blue-800 border-blue-200" },
  en_progreso: { label: "En Progreso", cls: "bg-amber-100 text-amber-800 border-amber-200" },
  en_espera: { label: "En Espera", cls: "bg-violet-100 text-violet-800 border-violet-200" },
  resuelto: { label: "Resuelto", cls: "bg-emerald-100 text-emerald-800 border-emerald-200" },
  cerrado: { label: "Cerrado", cls: "bg-slate-200 text-slate-700 border-slate-300" },
  // priority
  baja: { label: "Baja", cls: "bg-slate-100 text-slate-700 border-slate-200" },
  media: { label: "Media", cls: "bg-blue-100 text-blue-800 border-blue-200" },
  alta: { label: "Alta", cls: "bg-amber-100 text-amber-800 border-amber-200" },
  critica: { label: "Crítica", cls: "bg-red-100 text-red-800 border-red-200" },
};

export default function StatusBadge({ value, testid }) {
  const cfg = MAP[value] || { label: value || "—", cls: "bg-slate-100 text-slate-700 border-slate-200" };
  return (
    <span data-testid={testid}
      className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold ${cfg.cls}`}>
      {cfg.label}
    </span>
  );
}
